import { Expense } from '../model/expense';

// Builds a flow-conserving Sankey graph from an Expense tree.
//
// A Sankey node is sized max(inflow, outflow), so a net value X = ΣP − ΣM cannot be
// drawn with the deductions M flowing into it from the same side as P. Instead the
// gross splits: P → X before deductions → {X, M}. A deduction M therefore receives flow from the
// left, and its own breakdown fans out to the right — its orientation is reversed,
// and flips again at every nested deduction. See docs/design-01-expense-tree.md.

// 'in': flow leaves to the right (into the parent); components arrive from the left.
// 'out': flow arrives from the left (from the parent's gross); components leave to the right.
export type Orientation = 'in' | 'out';

// A node's effect on the diagram's total (its root): 'in' nodes add to it and 'out'
// nodes reduce it, flipped when the root itself is negative (a loss swaps sides).
export type Effect = 'result' | 'add' | 'deduct';

export interface FlowNode {
  name: string;
  kind: 'expense' | 'gross' | 'other';
  orientation: Orientation;
  effect: Effect;
  isRoot: boolean;
  signedValue?: number;   // amount shown on the label (model value; gross total; grouped sum)
  members?: Array<{ name: string; value: number }>;  // items merged into an 'other' node
}

export interface FlowLink {
  source: number;
  target: number;
  value: number;
  kind: 'add' | 'deduct'; // deduct: touches a node that is deducted from the total
  actual?: number;        // real amount when value has been rescaled (compressFlows)
}

export interface SankeyGraphData {
  nodes: FlowNode[];
  links: FlowLink[];
}

export interface SankeyGraphOptions {
  // Merge two or more siblings below this fraction of the largest flow into one
  // "Other" node, so hairline slivers don't crowd the diagram. 0 disables grouping.
  groupBelow?: number;
}

export function buildSankeyGraph(roots: Expense[], value: (e: Expense) => number,
                                 options: SankeyGraphOptions = {}): SankeyGraphData {
  const groupBelow = options.groupBelow ?? 0;
  if (groupBelow <= 0) return build(roots, value, 0);
  // The threshold is relative to the largest flow, which is only known once built.
  const ungrouped = build(roots, value, 0);
  const maxFlow = Math.max(0, ...ungrouped.links.map(l => l.value));
  return build(roots, value, groupBelow * maxFlow);
}

// Rescales every link width with f (e.g. √) so small flows stay visible. Widths then
// no longer add up at nodes; the real amount is kept in `actual` for tooltips.
export function compressFlows(graph: SankeyGraphData, f: (v: number) => number = Math.sqrt): SankeyGraphData {
  return {
    nodes: graph.nodes.map(n => ({ ...n })),
    links: graph.links.map(l => ({ ...l, value: f(l.value), actual: l.actual ?? l.value })),
  };
}

type Child = Expense | Omit<FlowNode, 'effect'>;  // an Expense to emit, or an already-grouped 'other' node

function build(roots: Expense[], value: (e: Expense) => number, minFlow: number): SankeyGraphData {
  const nodes: FlowNode[] = [];
  const links: FlowLink[] = [];
  const linked = new Set<string>();
  // Node identity is the Expense instance plus orientation: a shared instance is drawn
  // once per orientation, and seeing it both ways cannot create a cycle.
  const expenseIdx = { in: new Map<Expense, number>(), out: new Map<Expense, number>() };
  const grossIdx = { in: new Map<Expense, number>(), out: new Map<Expense, number>() };

  let rootSign = 1;  // sign of the root being emitted; a negative root swaps which side deducts
  const effectOf = (o: Orientation, isRoot: boolean): Effect =>
    isRoot ? 'result' : (o === 'in' ? 1 : -1) * rootSign > 0 ? 'add' : 'deduct';
  const addNode = (n: Omit<FlowNode, 'effect'>): number =>
    nodes.push({ ...n, effect: effectOf(n.orientation, n.isRoot) }) - 1;

  const addLink = (source: number, target: number, amount: number): void => {
    const key = `${source}-${target}`;
    if (amount <= 0 || linked.has(key)) return;
    const deduct = nodes[source].effect === 'deduct' || nodes[target].effect === 'deduct';
    links.push({ source, target, value: amount, kind: deduct ? 'deduct' : 'add' });
    linked.add(key);
  };

  const grossNode = (e: Expense, o: Orientation, total: number): number => {
    let idx = grossIdx[o].get(e);
    if (idx === undefined) {
      // In a deduction's reversed subtree the gross is the amount before its offsets.
      const name = o === 'in' ? `${e.label} before deductions` : `${e.label} before offsets`;
      idx = addNode({ name, kind: 'gross', orientation: o, isRoot: false, signedValue: total });
      grossIdx[o].set(e, idx);
    }
    return idx;
  };

  const emit = (e: Expense, o: Orientation, isRoot: boolean): number => {
    const existing = expenseIdx[o].get(e);
    if (existing !== undefined) return existing; // subtree already emitted

    const v = value(e);
    const idx = addNode({ name: e.label, kind: 'expense', orientation: o, isRoot, signedValue: v });
    expenseIdx[o].set(e, idx);

    // Split children by effective sign relative to this node's own sign, so that
    // Σpositive − Σnegative = |v| even when a child or the node itself is negative.
    const sign = v < 0 ? -1 : 1;
    let positive: Array<[Child, number]> = [];
    let negative: Array<[Child, number]> = [];
    for (const [op, child] of e.expenses) {
      if (op === '~' || !child.is_known) continue;
      const cv = value(child);
      if (cv === 0) continue;
      const effective = (op === '+' ? 1 : -1) * Math.sign(cv) * sign;
      (effective > 0 ? positive : negative).push([child, Math.abs(cv)]);
    }

    // Children on the positive side keep this node's orientation; deductions flip it.
    const flipped: Orientation = o === 'in' ? 'out' : 'in';
    positive = group(positive, o);
    negative = group(negative, flipped);
    const place = (child: Child, co: Orientation): number =>
      child instanceof Expense ? emit(child, co, false) : addNode(child);

    if (negative.length === 0) {
      for (const [child, w] of positive) {
        if (o === 'in') addLink(place(child, o), idx, w);
        else addLink(idx, place(child, o), w);
      }
      return idx;
    }

    const gross = grossNode(e, o, positive.reduce((sum, [, w]) => sum + w, 0));
    if (o === 'in') {
      for (const [child, w] of positive) addLink(place(child, o), gross, w);
      addLink(gross, idx, Math.abs(v));
      for (const [child, w] of negative) addLink(gross, place(child, flipped), w);
    } else {
      addLink(idx, gross, Math.abs(v));
      for (const [child, w] of negative) addLink(place(child, flipped), gross, w);
      for (const [child, w] of positive) addLink(gross, place(child, o), w);
    }
    return idx;
  };

  // Replaces two or more children below minFlow with one 'other' node. A lone small
  // child is kept: merging it would hide its name without saving any space.
  const group = (children: Array<[Child, number]>, o: Orientation): Array<[Child, number]> => {
    const small = children.filter(([, w]) => w < minFlow);
    if (small.length < 2) return children;
    const total = small.reduce((sum, [, w]) => sum + w, 0);
    const other: Omit<FlowNode, 'effect'> = {
      name: `Other (${small.length} items)`, kind: 'other', orientation: o, isRoot: false,
      signedValue: total,
      members: small.map(([c, w]) => ({ name: c instanceof Expense ? c.label : c.name, value: w })),
    };
    return [...children.filter(([, w]) => w >= minFlow), [other, total]];
  };

  for (const root of roots) {
    const v = value(root);
    if (v === 0) continue;
    rootSign = v < 0 ? -1 : 1;
    const idx = emit(root, 'in', true);
    nodes[idx].isRoot = true;
    nodes[idx].effect = 'result';
  }
  return { nodes, links };
}
