
import {Options, Vue } from 'vue-class-component';
import {Params} from "../model/param"
import {TaxBracket} from  "../model/marginal_tax"
import {defaultInsurancePercent} from "../model/config"

@Options({
  props: {
    msg: String,
    params: Params,
    equivalent_rent_weekly: Number,   // Equivalent Rent per week (cost of owning), for rent as a %
  },
  watch: {
    // The hold cannot outlast the loan. Watchers see the stored values whether set by a
    // slider or a number input (an @input handler runs before v-model and sees stale values).
    'params.config.loan_term'(this: InputParam, loan_term: number) {
      if (this.params.config.hold_term > loan_term) this.params.config.hold_term = Math.max(1, loan_term);
    },
    'params.config.hold_term'(this: InputParam, hold_term: number) {
      if (hold_term > this.params.config.loan_term) this.params.config.hold_term = this.params.config.loan_term;
    }
  }
})
export default class InputParam extends Vue {
  msg!: string;
  params!: Params;
  equivalent_rent_weekly!: number;
  deposit_percent=20;
  config = {
    debug: false,
    masked: false,
    prefix: '',
    suffix: '',
    thousands: ',',
    decimal: '.',
    precision: 0,
    disableNegative: false,
    disabled: false,
    min: null,
    max: null,
    allowBlank: false,
    minimumNumberOfCharacters: 0,
    modelModifiers: {
        number: true,
    },
    shouldRound: true,
    focusOnRight: false,
  }
  // The split is stored only as params.property.building_percent; land and building
  // amounts are derived from it. Each input below sets the percent, so all three
  // (land $, building $, %) always agree and sum to the property value.
  setBuildingPercent(percent: number): void {
      this.params.property.building_percent = Math.min(100, Math.max(0, Number(percent) || 0));
  }
  setBuildingValue(amount: number): void {
      const value = this.params.property.value;
      if (value > 0) this.setBuildingPercent(amount / value * 100);
  }
  setLandValue(amount: number): void {
      const value = this.params.property.value;
      if (value > 0) this.setBuildingPercent(100 - amount / value * 100);
  }
  // Slider ranges that depend on other parameters must always contain the current value
  // and be a whole number of intervals, or vue-slider rejects them.
  // Slider scales: a tick every `step`, labelled every `label_every` (unlabelled ticks keep
  // dense ranges readable). Mark values are whole multiples of the step, which are valid
  // slider values because each step is a multiple of that slider's interval.
  scaleMarks(min: number, max: number, step: number, label_every: number,
             format: (v: number) => string): Record<string, string> {
      const marks: Record<string, string> = {};
      const round = (v: number) => Math.round(v * 1e6) / 1e6;
      const multiple = (v: number, m: number) => Math.abs(v / m - Math.round(v / m)) < 1e-9;
      for (let k = Math.ceil(min / step - 1e-9); k * step <= max + 1e-9; k++) {
          const v = round(k * step);
          marks[String(v)] = multiple(v, label_every) ? format(v) : '';
      }
      return marks;
  }
  term_marks = this.scaleMarks(1, 50, 5, 5, v => `${v}`);
  rate_marks = this.scaleMarks(0, 20, 1, 5, v => `${v}%`);
  appreciation_marks = this.scaleMarks(-10, 20, 1, 5, v => `${v > 0 ? '+' : ''}${v}%`);
  insurance_marks = this.scaleMarks(0, 2, 0.1, 0.5, v => `${v}%`);
  // JP amounts are in yen: the same scales in ¥ would be ~1000 ticks, so use ¥5M / ¥50k.
  get offset_balance_marks(): Record<string, string> {
      const jp = this.params.location.country === 'JPN';
      return this.scaleMarks(0, this.offset_slider_max, jp ? 5_000_000 : 50_000, jp ? 10_000_000 : 100_000,
                             v => this.format_short(v));
  }
  get offset_contribution_marks(): Record<string, string> {
      return this.scaleMarks(0, 5000, 500, 1000, v => this.format_short(v));
  }
  format_short(amount: number): string {
      const c = this.params.location.currency;
      if (amount >= 1_000_000) return `${c}${amount / 1_000_000}M`;
      if (amount >= 1_000) return `${c}${amount / 1_000}k`;
      return `${c}${amount}`;
  }

  // Weekly rent: relative to Equivalent Rent (params.property.rent_relative_percent) or
  // a fixed amount (params.property.rent); rent_mode records which was set last.
  rent_marks = { '-50': '-50%', '-25': '-25%', '0': '0%', '25': '+25%', '50': '+50%' };
  get effective_rent(): number {
      if (this.params.property.rent_mode === 'relative') {
          return Math.max(0, this.equivalent_rent_weekly * (1 + this.params.property.rent_relative_percent / 100));
      }
      return this.params.property.rent;
  }
  get rent_percent(): number {
      if (this.params.property.rent_mode === 'relative') return this.params.property.rent_relative_percent;
      return this.equivalent_rent_weekly > 0 ? (this.params.property.rent / this.equivalent_rent_weekly - 1) * 100 : 0;
  }
  get rent_slider_percent(): number {
      return Math.min(50, Math.max(-50, Math.round(this.rent_percent)));
  }
  get rent_note(): string {
      const pct = Math.round(this.rent_percent);
      const vs = pct === 0 ? '= Equivalent Rent' : `${this.formatSignedPercent(pct)} vs Equivalent Rent`;
      const kept = this.params.property.rent_mode === 'relative' ? 'kept as a %' : 'kept as an amount';
      return `${vs} (${this.format_amount(this.equivalent_rent_weekly)}/wk) — ${kept}`;
  }
  formatSignedPercent(pct: number): string {
      return `${pct > 0 ? '+' : ''}${pct}%`;
  }
  setRentPercent(pct: number): void {
      this.params.property.rent_mode = 'relative';
      this.params.property.rent_relative_percent = Number(pct);
  }
  setRentAmount(amount: number): void {
      // money3 can re-emit its displayed value when that changes programmatically (e.g.
      // the cost of owning moved); only a real edit switches to a fixed amount.
      if (Math.abs(Number(amount) - Math.round(this.effective_rent)) < 0.5) return;
      this.params.property.rent_mode = 'fixed';
      this.params.property.rent = Math.max(0, Number(amount) || 0);
  }
  get offset_slider_max(): number {
      return Math.max(1000, Math.ceil(this.params.property.value / 1000) * 1000);
  }

  // Insurance is stored only as params.property.insurance_percent (of building value);
  // editing the amount sets the percent, and the amount follows the building value.
  get insurance_amount(): number {
      return this.params.property.building_value * this.params.property.insurance_percent / 100;
  }
  get insurance_slider_value(): number {
      return Math.min(2, Math.round(this.params.property.insurance_percent * 100) / 100);
  }
  format_percent_precise(percent: number): string {
      return `${Number(percent.toFixed(3))}%`;
  }
  setInsuranceAmount(amount: number): void {
      const building = this.params.property.building_value;
      if (building > 0) this.params.property.insurance_percent = Math.max(0, Number(amount) || 0) / building * 100;
  }
  // Changing the title resets insurance to its default: 0 for strata (the levy covers
  // the building), the country rate otherwise.
  setCommunityTitle(community_title: boolean): void {
      this.params.property.community_title = community_title;
      this.params.property.insurance_percent = defaultInsurancePercent(this.params.location.country, community_title);
  }

  format_percent(percent: number): string {
      return `${Math.round(percent * 10) / 10}%`;
  }
  format_amount(amount: number): string {
      return `${this.params.location.currency}${Math.round(amount).toLocaleString()}`;
  }
  get split_caption(): string {
      return `Land ${this.format_percent(100 - this.params.property.building_percent)}, ` +
             `Building ${this.format_percent(this.params.property.building_percent)}`;
  }

  tax_rate(enable: boolean, income: number) : string {
      if (enable) {
          let pct = TaxBracket.GetPercent(income)*100;
          return `${pct}%`;
      } else {
          return "N/A";
      }
  }

}
