import { JpSourceCgt } from "./jp_source_cgt";
import { Gearing } from "./gearing";
import { effectiveWeeklyRent } from "./effective_rent";

/**
 * Helper: resolve the investor tax residence with backwards-compat fallback to location.country.
 * Returns the effective tax-residence country code ("AUS" | "JPN" | etc.).
 */
function effectiveTaxResidence(params: Params, purchaser: { tax_residence: string }): string {
    return purchaser.tax_residence || params.location.country;
}

/** Returns true if any enabled purchaser is AU tax-resident. */
function hasAuResident(params: Params): boolean {
    return params.purchasers.some(p => p.enable && effectiveTaxResidence(params, p) === "AUS");
}

/**
 * Equity held on day one: property value less the amount borrowed.
 */
export class EquityAtPurchase extends Expense {
    constructor(loan_amount: number, property_value: number) {
        super("Equity at Purchase",
              "Property value less the amount borrowed, on the day of purchase.");
        this.update_upfront(property_value - loan_amount, 0);
    }
}

/**
 * Loan principal repaid by the end of the loan term: the whole loan, which becomes equity.
 */
export class PrincipalRepaid extends Expense {
    constructor(params: Params, loan_amount: number) {
        super("Principal Repaid by Loan End",
              `The whole loan, repaid as equity over the ${params.config.loan_term}-year term.`);
        this.update_upfront(loan_amount, 0);
    }
}

/**
 * Loan balance still owing when the property is sold at hold-end; it comes out of the
 * sale proceeds, so it is subtracted from the equity. Over the full loan term nothing is
 * owing, so its upfront (loan-term) amount is 0 and the balance appears only in the hold
 * view: the exit remainder is negative, making accumulated(hold) = 0 − (−balance) = balance.
 */
export class OutstandingPrincipal extends Expense {
    constructor(params: Params, loan_amount: number) {
        super("Outstanding Principal",
              `Loan balance still owing after the ${params.config.hold_term}-year hold, repaid from the sale proceeds. ` +
              `Zero if the property is held to the end of the ${params.config.loan_term}-year loan.`);
        const remaining_principal = MortgageInterest.calculateRemainingPrincipal(
            loan_amount,
            params.economy.loan_rate,
            params.config.loan_term,
            params.config.hold_term
        );
        this.update_upfront(0, -remaining_principal);
    }
}

/**
 * Represents the equity retained in the property
 */
export class RetainedEquity extends Expense {
    public at_purchase: EquityAtPurchase;
    public principal_repaid: PrincipalRepaid;
    public outstanding_principal: OutstandingPrincipal;

    constructor(params: Params, loan_amount: number, property_value: number) {
        super("Retained Equity",
              "Equity in the property: equity at purchase plus the principal repaid by the end of the loan, " +
              "less the balance still owing at sale. At hold-end this is value − loan balance still owing; " +
              "over the full loan term it is the whole property value.");

        this.at_purchase = new EquityAtPurchase(loan_amount, property_value);
        this.principal_repaid = new PrincipalRepaid(params, loan_amount);
        this.outstanding_principal = new OutstandingPrincipal(params, loan_amount);
        this.add(this.at_purchase);
        this.add(this.principal_repaid);
        this.sub(this.outstanding_principal);
    }
}

/**
 * Represents asset appreciation over the hold period
 */
export class AssetAppreciation extends Expense {
    constructor(params: Params, property_value: number) {
        super("Asset Appreciation",
              "Estimated increase in property value based on annual appreciation rate.");

        // Compound appreciation over the hold: gain = value × ((1 + rate)^hold − 1).
        // Appreciation after the sale is not the investor's and is not shown.
        const appreciation_rate = params.economy.appreciation_rate / 100.0;
        const hold_years = params.config.hold_term;
        const appreciated_value_at_hold = property_value * Math.pow(1 + appreciation_rate, hold_years);
        const appreciation_gain_at_hold = appreciated_value_at_hold - property_value;
        this.update_upfront(appreciation_gain_at_hold, 0);
    }
}

export class InitialEquity extends Expense {
    constructor(params: Params) {
        super("Initial Equity",
              "The initial downpayment or deposit for this investment.");
        this.update_upfront(params.config.deposit, 0);
    }
}

export class CGTax extends Expense {

    public cgt_tax : Array<Expense>;   // CGTTaxedAmount (AU) and, for JP property, JpSourceCgt / FITO nodes
    
    constructor(params: Params, 
                asset_appreciation: AssetAppreciation,
                depreciation?: Expense) {

        super("Capital Gains Tax",
              "Capital Gains tax at sale.")
        this.cgt_tax = [];

        const purchaser_cnt = params.purchasers.length;
        let enabled_cnt = 0;
        for (let i=0; i < purchaser_cnt; i++) {
            if (params.purchasers[i].enable) {
                enabled_cnt = enabled_cnt+1;
            }
        }

        if (!params.config.owner_occupier) {
            let j=0;
            let total_au_cgt = 0;
            for (let i=0; i < purchaser_cnt; i++) {
                if (params.purchasers[i].enable) {
                    // AU CGT fires for AU-resident purchasers (with backwards-compat fallback to location.country).
                    // Non-AU purchasers of JP property are covered by JpSourceCgt below; non-AU purchasers of
                    // AU property (foreign-resident AU CGT, no discount, non-resident rates) are not modelled.
                    const tax_residence = effectiveTaxResidence(params, params.purchasers[i]);
                    if (tax_residence !== "AUS") continue;

                    this.cgt_tax[j] = new CGTTaxedAmount(params,
                                                  `Appreciation, purchaser ${i}`,
                                                  params.purchasers[i],
                                                  asset_appreciation,
                                                  enabled_cnt);
                    this.add(this.cgt_tax[j]);
                    total_au_cgt += -this.cgt_tax[j].exit_remainder_amount;
                    j+=1;
                    if (depreciation != undefined) {
                        this.cgt_tax[j] = new CGTTaxedAmount(params,
                                                      `Depreciation, purchaser ${i}`,
                                                      params.purchasers[i],
                                                      depreciation,
                                                      enabled_cnt);
                        this.add(this.cgt_tax[j]);
                        total_au_cgt += -this.cgt_tax[j].exit_remainder_amount;
                        j+=1;
                    }
                }
            }

            // JP source CGT on any JP property: resident or non-resident rates per purchaser,
            // long/short-term by holding period. For AU-resident purchasers the AU CGT above
            // also applies (worldwide gains); FITO credits the JP CGT against it, capped at
            // the AU CGT. For JP-resident purchasers this node is the whole liability.
            if (params.location.country === "JPN") {
                const jp_cgt = new JpSourceCgt(params, asset_appreciation, depreciation, enabled_cnt);
                this.add(jp_cgt);
                if (hasAuResident(params)) {
                    const fito_cgt = new ForeignIncomeTaxOffsetCgt(jp_cgt, total_au_cgt);
                    this.sub(fito_cgt);
                }
            }
        }

        if (depreciation != undefined) {
            this.link(depreciation);
        }

    }
}

/**
 * Calculates total equity return from property ownership
 */
export class EquityReturn extends Expense {

    public retained_equity: RetainedEquity;
    public asset_appreciation: AssetAppreciation;
    public initial_equity: InitialEquity;
    public feed_equity?: FeedEquity;
    public cg_tax: CGTax;

    constructor(params: Params, 
                loan_amount: number, 
                property_value: number);
    constructor(params: Params, 
                loan_amount: number, 
                property_value: number, 
                ownership_cost: CostOfOwnership, 
                depreciation: Expense, 
                investment_income_to_pay_principal: Expense);
    constructor(params: Params, 
                loan_amount: number, 
                property_value: number, 
                ownership_cost?: CostOfOwnership, 
                depreciation?: Expense, 
                investment_income_to_pay_principal?: Expense) {
        super("Equity Return",
              "Total return on investment from property ownership, including equity buildup and asset appreciation.");

        this.retained_equity = new RetainedEquity(params, loan_amount, property_value);
        this.asset_appreciation = new AssetAppreciation(params, property_value);
        this.initial_equity = new InitialEquity(params);
        this.cg_tax = new CGTax(params, this.asset_appreciation, depreciation);


        this.add(this.retained_equity);
        this.add(this.asset_appreciation);

        this.sub(this.cg_tax);

        this.sub(this.initial_equity);
        if ((ownership_cost != undefined) && (investment_income_to_pay_principal != undefined) ) {
            // FeedEquity shows the cash shortfall the owner must inject each year:
            // (interest + principal + expenses) − rental income. It is LINKED, not
            // subtracted: rent, interest and expenses are already netted in
            // NetInvestmentIncome, and principal is already cash-out in cash_flow
            // and equity-in via RetainedEquity. Subtracting it here as well (as the
            // code did while it happened to read zero) would count the shortfall twice
            // in InvestmentReturn = NetInvestmentIncome + EquityReturn.
            const net_investment_income = investment_income_to_pay_principal as unknown as NetInvestmentIncome;
            this.feed_equity = new FeedEquity(
                params,
                net_investment_income.rental_income,
                ownership_cost.loan_interest,
                ownership_cost.loan_principle,
                ownership_cost.cost_expenses
            );
            this.link(this.feed_equity);
        }


    }
}

/**
 * Represents rental income from investment property
 */
export class GrossRentalIncome extends Expense {
    constructor(params: Params, equivalent_rent?: Expense) {
        const relative = params.property.rent_mode === "relative" && equivalent_rent !== undefined;
        const pct = params.property.rent_relative_percent;
        super("Gross Rental Income",
              "Income received from renting out the property." + (relative
                ? ` Set at ${pct === 0 ? "" : (pct > 0 ? pct + "% above " : -pct + "% below ")}Equivalent Rent (the cost of owning).`
                : ""),
              Expense.ONE_WEEK);

        // Only applies to investment properties
        if (params.config.owner_occupier) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        const weekly_rent = effectiveWeeklyRent(params, equivalent_rent);
        this.is_known = true;
        this.update_repeating(weekly_rent);
    }
}

export class FeeOnRentalIncome extends Expense {
    constructor(params: Params, gross_rent: Expense) {
        super("Rental Management Fees",
              "Fees related to renting out the property.", Expense.ONE_WEEK);

        // Only applies to investment properties
        if (params.config.owner_occupier) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        // Fee on the rent actually charged (which may follow Equivalent Rent).
        const weekly_fee = gross_rent.periodic(params.config.hold_term, Expense.ONE_WEEK) * params.property.rent_fee_ratio;
        this.is_known = true;
        this.update_repeating(weekly_fee);
    }
}

export class TaxOnRentalIncome extends Expense {
    constructor(params: Params,  gross_income: Expense, fees: Expense) {
        super("Rental Income Tax",
              "Tax on rental income from property (domestic case — property & purchaser in same jurisdiction).", Expense.ONE_YEAR);

        // Only applies to investment properties
        if (params.config.owner_occupier) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        const purchaser_cnt = params.purchasers.length;
        let enabled_cnt = 0;
        for (let i=0; i < purchaser_cnt; i++) {
            if (params.purchasers[i].enable) {
                enabled_cnt = enabled_cnt+1;
            }
        }
        for (let i=0; i < purchaser_cnt; i++) {
            if (params.purchasers[i].enable) {
                // Only fire for the domestic case (purchaser tax_residence matches property country).
                // Cross-jurisdictional cases are routed through AuTaxOnForeignRentalIncome
                // (which accounts for AU-allowable deductions) + JpNonResidentRentalTax + FITO.
                const tax_residence = effectiveTaxResidence(params, params.purchasers[i]);
                if (tax_residence !== params.location.country) continue;

                const taxed_amount = new TaxedAmountWithDeduction(
                    `Rent Income for purchaser ${i}`,
                    params.purchasers[i],
                    gross_income, fees,enabled_cnt);
                this.add(taxed_amount);
            }
        }
    }
}

export class NetRentalIncome extends Expense {

    public rental_income: GrossRentalIncome;
    public rental_fee: FeeOnRentalIncome;
    public rental_tax: TaxOnRentalIncome;

    constructor(params: Params, equivalent_rent?: Expense) {
        super("Net Rental Income",
              "Income received from renting out the property, minus expenses and tax.", Expense.ONE_WEEK);

        // Initialize properties first
        this.rental_income = new GrossRentalIncome(params, equivalent_rent);
        this.rental_fee = new FeeOnRentalIncome(params, this.rental_income);
        this.rental_tax = new TaxOnRentalIncome(params, this.rental_income, this.rental_fee);

        // Only applies to investment properties
        if (params.config.owner_occupier) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        this.add(this.rental_income);
        this.sub(this.rental_fee);
        this.sub(this.rental_tax);

    }
}


/**
 * Aggregates all tax-deductible expenses for investment properties
 */
export class TaxDeductibleExpenses extends Expense {

    public finance_cost: Expense;
    public ongoing_expenses: Expense;

    constructor(params: Params, ownership_cost: CostOfOwnership) {
        super("Tax Deductible Expenses",
              "All paid for expenses that are tax-deductible for investment properties (not owner-occupied).", Expense.ONE_YEAR);

        this.finance_cost = ownership_cost.loan_interest;
        this.ongoing_expenses = ownership_cost.cost_expenses;

        // Only add these as deductible if it's an investment property
        this.add(this.finance_cost);
        this.add(this.ongoing_expenses);

    }
}

/**
 * Calculates the tax benefit from deductible expenses
 */
export class TaxBenefit extends Expense {

    constructor(params: Params, reason: string, deduction: Expense) {

        const total_claim =  deduction.periodic(params.config.hold_term, Expense.ONE_YEAR);

        super(`Tax Benefit from ${reason} Deduction`,
              `Tax savings from ${total_claim} at your marginal tax rate.`, Expense.ONE_YEAR);

        // Only calculate if there are purchasers with income and it's not owner-occupied
        if (params.config.owner_occupier || params.purchasers.length === 0) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        // Calculate total income from all purchasers
        let total_purchasers = 0;
        for (const purchaser of params.purchasers) {
            if (purchaser.enable) {
                total_purchasers += 1;
            }
        }

        if (total_purchasers === 0) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        // Tax benefit applies to each purchaser at their tax-residence MTR.
        // For AU residents, deductions reduce AU tax on assessable income (including foreign
        // rental income — AU residents are taxed on worldwide income, so the same deductions
        // apply whether the property is in AU or overseas).
        //
        // For JP residents, the tax-benefit calc against JP brackets is a future extension
        // (JpNonResidentRentalTax handles the JP-side tax via MarginalTaxFor("JPN", ...),
        // but it's not surfaced as a "benefit" in this aggregator). Currently only AU MTR
        // benefit is captured here.
        const per_owner =  total_claim / total_purchasers;
        let tax_savings = 0;
        for (const purchaser of params.purchasers) {
            if (!purchaser.enable) continue;
            const tax_residence = effectiveTaxResidence(params, purchaser);
            if (tax_residence !== "AUS") continue;
            const tax_result = TaxBracket.MarginalTaxFor("AUS", purchaser.income, per_owner);
            tax_savings += tax_result.amount;
        }
        this.is_known = true;
        this.update_repeating(tax_savings);
    }
}

export class FeedEquity extends Expense {

    constructor(params: Params,
                rental_income: NetRentalIncome,
                loan_interest: Expense,
                loan_principal: Expense,
                ongoing_expenses: Expense) {

        // Actual cash flows, averaged over the hold (interest and principal are
        // upfront/exit-remainder nodes, so annual() would read 0 for them).
        const hold = params.config.hold_term;
        const rental_cash_in = rental_income.periodic(hold, Expense.ONE_YEAR);
        const interest_out = loan_interest.periodic(hold, Expense.ONE_YEAR);
        const principal_out = loan_principal.periodic(hold, Expense.ONE_YEAR);
        const expenses_out = ongoing_expenses.periodic(hold, Expense.ONE_YEAR);
        const total_cash_out = interest_out + principal_out + expenses_out;
        const cash_shortfall = total_cash_out - rental_cash_in;

        super("Feed Equity",
              `Additional cash required when rental income (${rental_cash_in.toFixed(0)}) cannot cover ` +
              `interest (${interest_out.toFixed(0)}) + principal (${principal_out.toFixed(0)}) + expenses (${expenses_out.toFixed(0)}). ` +
              `Shortfall: ${cash_shortfall.toFixed(0)}`,
              Expense.ONE_YEAR);

        // Only calculate for investment properties
        if (params.config.owner_occupier) {
            this.is_known = true;
            this.update_repeating(0);
            return;
        }

        // If rental income cannot cover total cash outflow, owner must feed the difference
        // Note: Interest payments are a loss (tax deductible), but principal payments build equity
        if (cash_shortfall > 0) {
            this.update_repeating(cash_shortfall);

            // Link the components for visibility in breakdown
            this.link(rental_income);
            this.link(loan_interest);
            this.link(loan_principal);
            this.link(ongoing_expenses);
        } else {
            // Positive cash flow - no feeding required
            this.update_repeating(0);
        }
    }
}

export class GrossTaxBenefits extends Expense {

    public tax_benefit_from_expenses: TaxBenefit;
    public tax_benefit_from_depreciation: TaxBenefit;

    constructor(params: Params, 
                tax_deductible_expenses: Expense,
                depreciation: Expense) {

        super("Gross Tax Benefits",
              "Reduction in tax due to various expenses.");

        this.tax_benefit_from_expenses = new TaxBenefit(params, "Expenses", tax_deductible_expenses);
        this.tax_benefit_from_depreciation = new TaxBenefit(params, "Depreciation",  depreciation);

        this.add(this.tax_benefit_from_expenses);
        this.add(this.tax_benefit_from_depreciation);
        this.link(depreciation);
        
    }
}

export class NetInvestmentIncome extends Expense {

    public rental_income: NetRentalIncome;
    public tax_deductible_expenses: TaxDeductibleExpenses;
    public tax_benefits : GrossTaxBenefits;
    public jp_non_resident_rental_tax?: JpNonResidentRentalTax;
    public au_tax_on_foreign_rental?: AuTaxOnForeignRentalIncome;
    public fito_rental?: ForeignIncomeTaxOffsetRental;

    constructor(params: Params, loan_amount: number,
                ownership_cost: CostOfOwnership, depreciation: Expense) {
        super("Net Investment Income",
              "Income or loss from property after expenses.");

        this.rental_income = new NetRentalIncome(params, ownership_cost.cost);
        this.tax_deductible_expenses = new TaxDeductibleExpenses(params, ownership_cost);
        this.tax_benefits = new GrossTaxBenefits(params, this.tax_deductible_expenses, depreciation);

        this.add(this.rental_income);
        this.sub(this.tax_deductible_expenses);
        this.add(this.tax_benefits);

        // Cross-jurisdictional tax surfaces (AU resident + JP property).
        // These classes self-gate: each is a no-op for same-jurisdiction scenarios.
        const split = params.purchasers.filter(p => p.enable).length || 1;
        if (params.location.country === "JPN" && !params.config.owner_occupier) {
            // Both bases deduct the same things: all ongoing outgoings (JP property taxes,
            // insurance, body corp), mortgage interest over the hold, and depreciation.
            this.jp_non_resident_rental_tax = new JpNonResidentRentalTax(
                params, this.rental_income.rental_income, this.rental_income.rental_fee,
                ownership_cost.cost_expenses, ownership_cost.loan_interest, depreciation, split);
            this.au_tax_on_foreign_rental = new AuTaxOnForeignRentalIncome(
                params, this.rental_income.rental_income, this.rental_income.rental_fee,
                ownership_cost.cost_expenses, ownership_cost.loan_interest, depreciation, split);
            this.fito_rental = new ForeignIncomeTaxOffsetRental(
                this.jp_non_resident_rental_tax, this.au_tax_on_foreign_rental);

            this.sub(this.jp_non_resident_rental_tax);
            this.sub(this.au_tax_on_foreign_rental);
            this.add(this.fito_rental);
        }

    }

}



/**
 * Complete investment return calculation including:
 * 1. Equity Return (capital gains)
 * 2. Rental Income
 * 3. Tax Deductible Expenses (for reference)
 * 4. Tax Deduction Benefit (actual tax savings)
 */
export class InvestmentReturn extends Expense {

    public depreciation: Depreciation;
    public investment_income: NetInvestmentIncome;
    public equity_return: EquityReturn;
    public gearing: Gearing;

    constructor(params: Params, loan_amount: number, property_value: number,
                ownership_cost: CostOfOwnership) {
        super("Investment Return",
              "Total return over the hold: net investment income + equity return − principal repaid from cash. " +
              "Principal appears in Retained Equity as equity built and is cash paid out during the hold, so it is netted here; " +
              "what remains is net income + appreciation − CGT − sunk purchase costs.");

        // Depreciation is used only as a tax deduction (GrossTaxBenefits) and to adjust the CGT cost base.
        this.depreciation = new Depreciation(params);
        this.investment_income = new NetInvestmentIncome(params, loan_amount, ownership_cost, this.depreciation);
        this.equity_return = new EquityReturn(params, loan_amount, property_value, ownership_cost, this.depreciation, this.investment_income);

        // Gearing is a diagnostic recombination of already-composed values (rent, PM fee,
        // outgoings, year-1 interest) — a separate view of the model, not a new cash flow.
        // Deliberately not add/sub/linked into this root's own total (mirrors how
        // CostOfOwnership exposes .cost and .cash_flow as two independent views).
        this.gearing = new Gearing(
            params, loan_amount,
            this.investment_income.rental_income.rental_income,
            this.investment_income.rental_income.rental_fee,
            this.investment_income.tax_deductible_expenses.ongoing_expenses
        );

        this.add(this.investment_income);
        this.add(this.equity_return);
        // Principal repaid during the hold: counted as equity in RetainedEquity, but it was cash out
        // (cost_of_ownership.cash_flow). Net it so the root is a true return on cash invested.
        this.sub(ownership_cost.loan_principle);


    }
}
