
import { Options, Vue } from 'vue-class-component';

import * as d3 from 'd3';
import { sankey, sankeyLinkHorizontal, SankeyGraph, SankeyNode, SankeyLink } from 'd3-sankey';

import {Expense} from "../model/expense"
import ToggleSwitchGroup from './ToggleSwitchGroup.vue';

import { Params } from '../model/param';
import { watch } from 'vue';
import { buildSankeyGraph, compressFlows, FlowNode, FlowLink } from './sankey_graph';

// Links on the deduction side of the tree are drawn in the reverse direction; a
// distinct colour lets the reader tell "where it went" from "what it's made of".
const DEDUCT_COLOR = '#c0504d';
// The result (the diagram's total) and the intermediate "before deductions" totals.
const RESULT_COLOR = '#2c3e50';
const GROSS_COLOR = '#adb5bd';
// Within a column: the result on top, then what adds to it, then what is deducted.
const EFFECT_ORDER: Record<string, number> = { result: 0, add: 1, deduct: 2 };

// Linear view: siblings below this fraction of the largest flow merge into "Other".
const GROUP_BELOW = 0.02;
// Chart height scales with the busiest column: this much per node, within
// MIN_CHART_HEIGHT and the window height.
const ROW_HEIGHT = 48;
const MIN_CHART_HEIGHT = 240;

// Vertical space a 12px label needs; labels that would collide are left to the tooltip.
const LABEL_HEIGHT = 13;

@Options({
  components: {
    ToggleSwitchGroup
  },
  props: {
    title: String,
    view_period: Number,
    expenses: Array,
    params: Params,
    period_only: Boolean,   // only the per-period view is offered (e.g. Equivalent Rent)
  }
})
export default class SankeyDiagram extends Vue {

  view_period!: number;
  expenses!: Expense[];
  params!: Params;
  title!: string;
  period_only!: boolean;
  private debounceTimer: number | null = null;
  describe_period=Expense.describe_period;
    
    categoryOptions = [
        {key: 'period_expense',
         label: `Amount per ${this.describe_period(this.view_period)}` ,
         desc: ""
        },
        {key: 'hold_expense',
         label: `Amount commited while holding` ,
         desc: ""
        },
        {key: 'total_expense',
         label: `Amount commited with loan` ,
         desc: ""
        }
    ];
    selected_category: string = this.categoryOptions[0].key;

    get visibleCategoryOptions(): Array<{ key: string; label: string; desc: string }> {
        return this.period_only ? this.categoryOptions.slice(0, 1) : this.categoryOptions;
    }

    scaleOptions = [
        {key: 'linear',
         label: 'Linear',
         desc: 'Widths proportional to amounts; small items grouped into "Other"'
        },
        {key: 'compressed',
         label: 'Compressed',
         desc: 'Widths proportional to √amount so every small item is visible; widths no longer add up'
        }
    ];
    selected_scale = 'compressed';

  mounted(): void {
    // A period-only diagram cannot stay on a hidden hold/loan view.
    watch(() => this.period_only, (period_only) => {
      if (period_only) this.selected_category = 'period_expense';
    }, { immediate: true });

    this.renderSankey();

    // Watch for changes and re-render with debouncing
    watch(() => [this.expenses, this.view_period, this.params, this.selected_category, this.selected_scale], () => {
      if (this.debounceTimer !== null) {
        clearTimeout(this.debounceTimer);
      }
      this.debounceTimer = window.setTimeout(() => {
        this.renderSankey();
        this.debounceTimer = null;
      }, 150);
    }, { deep: true });
  }

  renderSankey(): void {
    // Update category label based on current period
    this.categoryOptions[0].label = `Amount per ${this.describe_period(this.view_period)}`;

    // Validate required props - return early if invalid
    if (!this.expenses || !this.expenses.length || !this.params || this.view_period === undefined) {
      return;
    }

    const container = this.$refs.sankeyRef as HTMLElement;
    if (!container) return;

    // Clear previous chart
    d3.select(container).selectAll('*').remove();

    // Prepare data
    const value = (e: Expense) => this.calcValue(e);
    const { nodes, links } = this.selected_scale === 'compressed'
      ? compressFlows(buildSankeyGraph(this.expenses, value))
      : buildSankeyGraph(this.expenses, value, { groupBelow: GROUP_BELOW });
    if (nodes.length === 0) {
      // d3-sankey cannot lay out an empty graph (e.g. no upfront amount in the loan view).
      d3.select(container).append('p').text('Nothing to show for this view.');
      return;
    }

    // Set dimensions
    const windowWidth = window.innerWidth;
    const windowHeight = window.innerHeight;

    const margin = { winner: 10, wouter: 90, houter: 90, hinner: 10 };
    const width = windowWidth - margin.winner - margin.wouter;
    const maxHeight = windowHeight - margin.hinner - margin.houter;

    const sankeyLayout = sankey<FlowNode, FlowLink>()
      .nodeWidth(15)
      .nodePadding(10)
      // Result first within its column, deductions grouped below it.
      .nodeSort((a: FlowNode, b: FlowNode) => EFFECT_ORDER[a.effect] - EFFECT_ORDER[b.effect]);
    const layout = (h: number): SankeyGraph<FlowNode, FlowLink> => sankeyLayout
      .extent([[1, 1], [width - 1, h - 5]])({
        nodes: nodes.map(d => ({ ...d })),
        links: links.map(d => ({ ...d }))
      });

    // A first layout assigns columns; size the chart to the busiest one, then lay out again.
    const perColumn = new Map<number, number>();
    for (const n of layout(maxHeight).nodes) {
      const column = Math.round(n.x0 || 0);
      perColumn.set(column, (perColumn.get(column) || 0) + 1);
    }
    const busiest = Math.max(...perColumn.values());
    const height = Math.max(MIN_CHART_HEIGHT, Math.min(maxHeight, busiest * ROW_HEIGHT));
    const graph = layout(height);

    // Create SVG
    const svg = d3.select(container)
      .append('svg')
      .attr('width', width + margin.winner*2)
      .attr('height', height  + margin.hinner*2)
      .append('g')
      .attr('transform', `translate(${margin.winner},${margin.hinner})`);

    // Color scale: per-name colours for what adds; fixed colours carry the sign.
    // Red is reserved for deductions, so it is dropped from the palette for additions.
    const color = d3.scaleOrdinal(d3.schemeCategory10.filter(c => c !== '#d62728'));
    const fill = (d: FlowNode): string =>
      d.effect === 'result' ? RESULT_COLOR
        : d.kind === 'gross' ? GROSS_COLOR
        : d.effect === 'deduct' ? DEDUCT_COLOR
        : color(d.name);

    // Add links
    svg.append('g')
      .selectAll('path')
      .data(graph.links)
      .join('path')
      .attr('d', sankeyLinkHorizontal())
      .attr('stroke', (d: SankeyLink<FlowNode, FlowLink>) => {
        if (d.kind === 'deduct') return DEDUCT_COLOR;
        return fill(d.source as SankeyNode<FlowNode, FlowLink>);
      })
      .attr('stroke-width', (d: SankeyLink<FlowNode, FlowLink>) => Math.max(1, d.width || 0))
      .attr('fill', 'none')
      .attr('opacity', 0.5)
      .append('title')
      .text((d: SankeyLink<FlowNode, FlowLink>) => {
        const sourceNode = d.source as SankeyNode<FlowNode, FlowLink>;
        const targetNode = d.target as SankeyNode<FlowNode, FlowLink>;
        return `${sourceNode.name} → ${targetNode.name}\n${this.formatAmount(d.actual ?? d.value)}`;
      });

    // Add nodes
    const node = svg.append('g')
      .selectAll('rect')
      .data(graph.nodes)
      .join('g');

    node.append('rect')
      .attr('x', (d: SankeyNode<FlowNode, FlowLink>) => d.x0 || 0)
      .attr('y', (d: SankeyNode<FlowNode, FlowLink>) => d.y0 || 0)
      .attr('height', (d: SankeyNode<FlowNode, FlowLink>) => (d.y1 || 0) - (d.y0 || 0))
      .attr('width', (d: SankeyNode<FlowNode, FlowLink>) => (d.x1 || 0) - (d.x0 || 0))
      .attr('fill', (d: SankeyNode<FlowNode, FlowLink>) => fill(d))
      .attr('opacity', 0.8)
      .append('title')
      .text((d: SankeyNode<FlowNode, FlowLink>) => this.nodeTooltip(d));

    // Add labels
    const labelled = this.labelledNodes(graph.nodes);
    node.filter((d: SankeyNode<FlowNode, FlowLink>) => labelled.has(d))
      .append('text')
      .attr('x', (d: SankeyNode<FlowNode, FlowLink>) => (d.x0 || 0) < width / 2 ? (d.x1 || 0) + 6 : (d.x0 || 0) - 6)
      .attr('y', (d: SankeyNode<FlowNode, FlowLink>) => ((d.y1 || 0) + (d.y0 || 0)) / 2)
      .attr('dy', '0.35em')
      .attr('text-anchor', (d: SankeyNode<FlowNode, FlowLink>) => (d.x0 || 0) < width / 2 ? 'start' : 'end')
      .text((d: SankeyNode<FlowNode, FlowLink>) => this.nodeLabel(d))
      .style('font-size', (d: SankeyNode<FlowNode, FlowLink>) => d.effect === 'result' ? '13px' : '12px')
      .style('font-weight', 'bold');

  }

  calcValue(expense: Expense) : number  {
      if (this.selected_category == 'period_expense') {
          return expense.periodic(this.params.config.hold_term, this.view_period);
      }
      if (this.selected_category == 'hold_expense') {
          return expense.accumulated(this.params.config.hold_term);
      }
      if (this.selected_category == 'total_expense') {
          return expense.over_loan_term(this.params.config.loan_term);
      }
      return 0;
  }

  // Chooses which nodes get a visible label: within each column, roots and then larger
  // bars claim their label's vertical band first; a label that would overlap one
  // already placed is skipped (its node keeps the hover tooltip).
  labelledNodes(nodes: SankeyNode<FlowNode, FlowLink>[]): Set<SankeyNode<FlowNode, FlowLink>> {
    const height = (d: SankeyNode<FlowNode, FlowLink>) => (d.y1 || 0) - (d.y0 || 0);
    const centre = (d: SankeyNode<FlowNode, FlowLink>) => ((d.y0 || 0) + (d.y1 || 0)) / 2;
    const byPriority = [...nodes].sort((a, b) => Number(b.isRoot) - Number(a.isRoot) || height(b) - height(a));
    const placed = new Map<number, number[]>();  // column x0 → label centres
    const labelled = new Set<SankeyNode<FlowNode, FlowLink>>();
    for (const d of byPriority) {
      const column = placed.get(d.x0 || 0) ?? [];
      if (column.every(y => Math.abs(y - centre(d)) >= LABEL_HEIGHT)) {
        column.push(centre(d));
        placed.set(d.x0 || 0, column);
        labelled.add(d);
      }
    }
    return labelled;
  }

  // "+ Name : $x" / "− Name : $x" / "= Name : $x": the prefix carries the effect on the
  // total, so non-result amounts show their magnitude (no "− … : -$30"). The result keeps
  // its sign, so a loss reads "= Name : -$40". Intermediate totals have no prefix.
  nodeLabel(d: FlowNode): string {
    const amount = d.signedValue ?? 0;
    if (d.effect === 'result') return `= ${d.name} : ${this.formatAmount(amount)}`;
    const prefix = d.kind === 'gross' ? '' : d.effect === 'deduct' ? '− ' : '+ ';
    return `${prefix}${d.name} : ${this.formatAmount(Math.abs(amount))}`;
  }

  nodeTooltip(d: FlowNode): string {
    const heading = this.nodeLabel(d);
    if (!d.members) return heading;
    return [heading, ...d.members.map(m => `  ${m.name} : ${this.formatAmount(m.value)}`)].join('\n');
  }

  formatAmount(displayValue: number): string {
    const currency = this.params.location.currency;
    const symbol = currency === 'JPY' ? '¥' : '$';
    const divisor = currency === 'JPY' ? 10000 : 1000;

    const sign = displayValue < 0 ? '-' : '';
    const magnitude = Math.abs(displayValue);
    if (magnitude >= divisor) {
      const suffix = currency === 'JPY' ? '万' : 'k';
      const formatted = (magnitude / divisor).toFixed(3);
      return `${sign}${symbol}${formatted}${suffix}`;
    } else {
      const formatted = Math.round(magnitude);
      return `${sign}${symbol}${formatted}`;
    }
  }
}
