
import {Options, Vue } from 'vue-class-component';
import {reactive} from 'vue';
import {ConfigLoad, ConfigRefresh} from "./model/config"
import {Params} from "./model/param"
import {CostOfOwnership} from "./model/cost_of_ownership"
import {LoanAmount} from "./model/loan_amount"
import {Expense} from "./model/expense"
import {EquityReturn} from "./model/investment_return"
import {InvestmentReturn} from "./model/investment_return"
import {saveToURL, loadFromURL, saveToCookie, loadFromCookie, clearCookie} from "./model/persistence"
import InputParam from './components/InputParam.vue';
import OutputTable from './components/OutputTable.vue';
import Location from './components/Location.vue';


@Options({
  props: {
    query: Object
  },
  components: {
    Location,
    InputParam,
    OutputTable,
  },
  computed: {
    loan_amount(): LoanAmount {
        console.log(`app: new loan amount`)
        return new LoanAmount(this.params);
    },
    cost_of_ownership(): CostOfOwnership {
        console.log(`app: new cost of ownership for ${this.params.location.postcode}`)
        let cost_of_ownership = new CostOfOwnership(this.params,
                                                      this.loan_amount);
        return cost_of_ownership;
    },
    equity_return(): EquityReturn {
        console.log(`app: new equity return`)
        return new EquityReturn(this.params,
                                this.loan_amount.upfront_amount,
                                this.params.property.value);
    },
    investment_return(): InvestmentReturn {
        console.log(`app: new investment return`)
        return new InvestmentReturn(this.params,
                                    this.loan_amount.upfront_amount,
                                    this.params.property.value,
                                    this.cost_of_ownership);
    }
  }
})

export default class App extends Vue {
     params!: Params;
     componentKey = 0;
     loaded = false;
     view_period = Expense.ONE_WEEK;
     weekPeriod = Expense.ONE_WEEK;
     data(): Record<string, unknown>  {
         var params = reactive(new Params());
         return {
             'params' : params,
             'componentKey': 0,
             'loaded': false
         }
     }
     async mounted(): Promise<void> {
         const postcode: string|undefined = this.$route.query["postcode"] as string || undefined;
         const country = process.env.VUE_APP_COUNTRY || "JPN";
         const countryFixed = process.env.VUE_APP_COUNTRY_FIXED === "true";

         // Country defaults first, then saved parameters (URL, else cookie) on top.
         // Loading saved parameters before ConfigLoad let the defaults overwrite them.
         await ConfigLoad(this.params, country, countryFixed, postcode);
         if (!loadFromURL(this.params)) {
             loadFromCookie(this.params);
         }
         this.loaded = true;
     }
     updatePostcode(value: string): void {
         console.log(`app: update to postcode ${value}`)
         this.params.location.postcode = value;
         ConfigRefresh(this.params);
         this.forceComponentRebuild();
     }
     updateCountry(value: string): void {         
         console.log(`app: update to country ${value}`)
         this.params.location.country = value;
         ConfigRefresh(this.params);
         this.forceComponentRebuild();
     }
     forceComponentRebuild(): void {
         (this.$refs.inputParam as InstanceType<typeof InputParam>).$forceUpdate();
         (this.$refs.outputTable as InstanceType<typeof OutputTable>).$forceUpdate();
         this.componentKey += 1;
         console.log(`app: rebuld ${this.componentKey}`)
     }
     saveToURLHandler(): void {
         const url = saveToURL(this.params);
         window.history.pushState({}, '', url);
         alert('Parameters saved to URL! You can bookmark or share this link.');
     }
     saveToCookieHandler(): void {
         saveToCookie(this.params);
         alert('Parameters saved to browser cookie!');
     }
     loadFromCookieHandler(): void {
         if (loadFromCookie(this.params)) {
             ConfigRefresh(this.params);
             this.forceComponentRebuild();
             alert('Parameters loaded from cookie!');
         } else {
             alert('No saved parameters found in cookie.');
         }
     }
     async clearCookieHandler(): Promise<void> {
         clearCookie();
         const country = process.env.VUE_APP_COUNTRY || "JPN";
         const countryFixed = process.env.VUE_APP_COUNTRY_FIXED === "true";
         await ConfigLoad(this.params, country, countryFixed, undefined);
         this.forceComponentRebuild();
         alert('Saved parameters cleared and defaults restored!');
     }
}
