
import {Options, Vue} from 'vue-class-component';
import {CostOfOwnership} from "../model/cost_of_ownership"
import {LoanAmount} from "../model/loan_amount"
import {EquityReturn} from "../model/investment_return"
import {InvestmentReturn} from "../model/investment_return"
import {Expense} from "../model/expense"
import {format as money_format} from 'v-money3';
import {Params} from "../model/param"

@Options({
    props: {
      msg: String,
      loan_amount: LoanAmount,
      cost_of_ownership: CostOfOwnership,
      equity_return: EquityReturn,
      investment_return: InvestmentReturn,
      params: Params,
    },
    watch: {
        // Investment Return is hidden for owner-occupiers; don't leave it selected.
        'params.config.owner_occupier'(this: OutputTable, owner_occupier: boolean) {
            if (owner_occupier && this.selectedCategory == 'investment_return') {
                this.selectedCategory = 'cost_of_ownership';
            }
        }
    }
})

export default class OutputTable extends Vue {
    // Props (declared in @Options above)
    loan_amount!: LoanAmount;
    cost_of_ownership!: CostOfOwnership;
    equity_return!: EquityReturn;
    investment_return!: InvestmentReturn;
    params!: Params;

    child_visible = true;
    view_period = Expense.ONE_WEEK;
    alias_money_format = money_format;
    describe_period = Expense.describe_period;

    /**
     * Mapping of category keys to their corresponding Expense objects
     * This is the single source of truth for available categories
     */
    get expenseMap(): Record<string, Expense> {
        const map: Record<string, Expense> = {
            'cost_of_ownership': this.cost_of_ownership.cost,
            'loan_amount': this.loan_amount,
            'finance_cost': this.cost_of_ownership.cost_finance,
            'cash_flow': this.cost_of_ownership.cash_flow,
            'ongoing_expenses': this.cost_of_ownership.cost_expenses,
            'equity_return': this.equity_return,
        };
        // Rental income and investment tax effects only apply to an investment property.
        if (!this.params.config.owner_occupier) {
            map['investment_return'] = this.investment_return;
        }
        return map;
    }

    /**
     * Dynamically generate category options from Expense objects
     * Uses the label and desc from each Expense class instance
     */
    get categoryOptions(): Array<{ key: string; label: string; desc: string }> {
        return Object.entries(this.expenseMap).map(([key, expense]) => ({
            key,
            label: expense.label,
            desc: expense.desc
        }));
    }

    selectedCategory = 'cost_of_ownership';

    // Equivalent Rent is a rent: only its per-period amount is meaningful, so the
    // "committed while holding" / "committed with loan" views are hidden for it.
    get periodOnly(): boolean {
        return this.selectedCategory == 'cost_of_ownership';
    }

    get selectedExpense(): Expense {
        return this.expenseMap[this.selectedCategory];
    }

}

