
import {Vue, Options} from 'vue-class-component';
import {Params} from "../model/param"
import {PostcodeToState} from "../model/aus_state"
import {ConfigCurrency} from "../model/config"
import {Postcode2Lga} from "../model/postcode2lga"

@Options({
  props: {
    msg: String,
    params: Params
  },
  emits: ['update:postcode', 'update:country']
})

export default class Location extends Vue {
  msg!: string;
  params!: Params;
  lga(postcode: string) : string {
      return Postcode2Lga(postcode);
  }
  state(postcode: string) : string {
      return PostcodeToState(postcode);
  }
  currency(country: string) : string {
      return ConfigCurrency(country);
  }
  updatePostcode(event: Event): void {
      const target = event.target as HTMLInputElement;
      this.$emit('update:postcode', target.value);
  }
  updateCountry(event: Event): void {
      const target = event.target as HTMLInputElement;
      const value = target.value;
      this.$emit('update:country', value);
  }
}
